<script setup lang="ts">
import {ref,onMounted} from 'vue'
interface Diagnostics {version:string;checks:{name:string;ok:boolean;message:string}[];storage:{physical_bytes:number;active_bytes:number;limit_bytes:number;free_bytes:number;warning:boolean}}
const data=ref<Diagnostics|null>(null),error=ref(''),busy=ref(false)
const size=(n:number)=>(n/1024**3).toLocaleString('pt-BR',{maximumFractionDigits:3})+' GiB'
async function load(){busy.value=true;error.value='';try{const r=await fetch('/api/diagnostics');const body=await r.json();if(!r.ok)throw new Error(body.detail||'Diagnóstico indisponível.');data.value=body}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="settings-section" aria-labelledby="diagnostics-heading"><div class="section-heading"><h2 id="diagnostics-heading" tabindex="-1">Diagnóstico</h2><button class="button small" :disabled="busy" @click="load">{{busy?'Verificando…':'Verificar novamente'}}</button></div><p class="muted">Verificações locais. Nenhum diagnóstico é enviado automaticamente.</p><p v-if="error" role="alert">{{error}}</p><template v-if="data"><dl class="diagnostic-checks"><template v-for="check in data.checks" :key="check.name"><dt><span :class="['status-badge',check.ok?'positive':'warning']">{{check.ok?'OK':'Verificar'}}</span> {{check.name}}</dt><dd>{{check.message}}</dd></template></dl><p>Dados ativos: {{size(data.storage.active_bytes)}} de {{size(data.storage.limit_bytes)}}. Arquivos em disco: {{size(data.storage.physical_bytes)}}. Livre: {{size(data.storage.free_bytes)}}.</p><p class="field-hint">O banco reutiliza páginas liberadas; o tamanho físico pode continuar maior após a limpeza. Para pedir ajuda, informe versão {{data.version}}, distribuição, mensagem e como reproduzir. Nunca inclua chave, acesso local ou bancos pessoais.</p><a class="text-button" href="https://github.com/Alexsander33set/vatilume/issues/new/choose" target="_blank" rel="noopener noreferrer">Abrir solicitação de suporte</a></template></section></template>
